/**
 * 远程数据安全转换工具
 *
 * 作用：
 * - 所有远程数据（GitHub data/*.json）在消费前必须经过这里的安全转换
 * - 转换失败时返回 null，让调用方自动回退到本地默认数据
 * - 杜绝因数据结构不匹配导致的 undefined 报错和白屏
 */

import { migrateI18n, type I18nText } from './i18n-text';
import { logger } from '@lark-apaas/client-toolkit-lite';

/**
 * 安全地执行远程数据转换函数
 * 包裹 try-catch，失败时返回 null 并记录日志
 */
export function safeTransform<T>(
  moduleName: string,
  transformFn: () => T,
): T | null {
  try {
    return transformFn();
  } catch (err) {
    logger.error(
      `[RemoteData] Transform failed for "${moduleName}": ${String(err)}`
    );
    return null;
  }
}

/**
 * 安全读取对象属性，不存在或类型不对时返回默认值
 */
export function safeStr(val: unknown, fallback = ''): string {
  return typeof val === 'string' ? val : fallback;
}

export function safeNum(val: unknown, fallback = 0): number {
  const n = Number(val);
  return isNaN(n) ? fallback : n;
}

export function safeBool(val: unknown, fallback = false): boolean {
  return typeof val === 'boolean' ? val : fallback;
}

export function safeArr<T>(val: unknown): T[] {
  return Array.isArray(val) ? (val as T[]) : [];
}

/**
 * 安全地将可能是字符串也可能是 I18nText 的值转换为 I18nText
 * 空值 / 非对象非字符串 → 返回空 I18nText
 */
export function safeI18n(val: unknown): I18nText {
  return migrateI18n(val as string | I18nText | undefined | null);
}

/**
 * 安全地从多语言对象或字符串中提取当前语言的文本
 * 用于 SEO / Footer 等扁平字符串场景
 */
export function extractI18nStr(
  val: unknown,
  lang: string,
  fallback = '',
): string {
  if (!val || typeof val !== 'object') {
    return typeof val === 'string' ? val : fallback;
  }
  const obj = val as Record<string, unknown>;
  const target = obj[lang];
  if (typeof target === 'string' && target.trim()) return target;
  const en = obj.en;
  if (typeof en === 'string' && en.trim()) return en;
  return fallback;
}
